#!/usr/bin/env bash
#
# Wizard: Dump Live Schema (Read-Only) & Re-link to Staging
# Generated by the wizard skill.
#
# Safety:
#   - READ-ONLY on live: only dumps schema (no data, no writes, no DDL).
#   - Never stores or prints the live database password.
#   - Guarantees CLI is linked back to STAGING before exiting.

set -euo pipefail

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=4
_STAGE_INDEX=0

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · Read-only live schema extraction%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard safely dumps the live database schema (DDL only, 0 data)\n' "$DIM"
  printf '  and immediately re-links to the staging project.%s\n\n' "$RESET"
  printf '  %s• LIVE ref:%s    ffwcjldmmddcxlisntgt (READ-ONLY)\n' "$BOLD" "$RESET"
  printf '  %s• STAGING ref:%s uedyifxpddbpgjptuhwo (TARGET)\n\n' "$BOLD" "$RESET"
  pause "Press Enter when ready to start..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue...}" "$RESET"
  read -r _ || true
}

run_wizard() {

LIVE_REF="ffwcjldmmddcxlisntgt"
STAGING_REF="uedyifxpddbpgjptuhwo"

banner "Live Schema Extraction & Staging Re-link Wizard"

# ── Stage 1: Link to Live ─────────────────────────────────────────────────
stage "Link CLI to LIVE project (read-only)"
say "Connects the Supabase CLI to the live database so we can perform a read-only schema dump."
step "We will run: supabase link --project-ref $LIVE_REF"
note "Enter your LIVE database password when prompted by the CLI."
note "(Your password is never stored or echoed to any file)."
printf '\n'
pause "Press Enter to execute the link command..."

supabase link --project-ref "$LIVE_REF"

# ── Stage 2: Schema Dump ──────────────────────────────────────────────────
stage "Dump public schema from LIVE"
say "Dumps only the public SQL schema from the live database into a local file without touching any user data or storage files."
step "We will run: supabase db dump --schema public -f supabase/schema_live.sql"
printf '\n'
pause "Press Enter to run the schema dump..."

mkdir -p supabase
supabase db dump --schema public -f supabase/schema_live.sql

if [[ ! -s supabase/schema_live.sql ]]; then
  printf '\n  %s❌ ERROR: supabase/schema_live.sql is empty or was not created.%s\n' "$RED" "$RESET"
  exit 1
fi

printf '\n  %s✓ Schema dumped successfully to supabase/schema_live.sql%s\n\n' "$GREEN" "$RESET"
pause "Press Enter to switch back to staging..."

# ── Stage 3: Link back to Staging ─────────────────────────────────────────
stage "Switch link BACK to STAGING"
say "Immediately disconnects from the live project and switches the CLI back to staging to prevent accidental writes."
step "We will run: supabase link --project-ref $STAGING_REF"
note "Enter your STAGING database password when prompted."
printf '\n'
pause "Press Enter to re-link to staging..."

supabase link --project-ref "$STAGING_REF"

# ── Stage 4: Verification ─────────────────────────────────────────────────
stage "Verify active project is STAGING"
say "Verifies that the linked project is strictly staging before any further operations."

CURRENT_REF=""
if [[ -f "supabase/.temp/project-ref" ]]; then
  CURRENT_REF=$(tr -d '[:space:]' < "supabase/.temp/project-ref")
fi

printf '  Active linked project ref: %s%s%s\n' "$BOLD" "$CURRENT_REF" "$RESET"

if [[ "$CURRENT_REF" != "$STAGING_REF" ]]; then
  printf '\n  %s❌ SAFETY FAILURE: Linked project is NOT staging (%s != %s)!%s\n' "$RED" "$CURRENT_REF" "$STAGING_REF" "$RESET"
  exit 1
fi

printf '\n  %s✓ Verified: Active CLI link is strictly STAGING (%s).%s\n\n' "$GREEN" "$STAGING_REF" "$RESET"

supabase projects list

printf '\n%s%s  ✓ Wizard Complete! LIVE was not modified and STAGING is active.%s\n\n' "$BOLD" "$GREEN" "$RESET"
}

run_wizard "$@"; exit
